using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
public static class CP6Expanded {
 [Serializable]class EventRow{public string skill,stage,target;public long attack;public int pulse,frame;public Vector3 origin,direction;public float before,after,time;}
 [Serializable]class Fixture{public Vector3[] positions;public string note;}
 static string sample;static CP6Probe probe;static int releases,damages,captures;static float clock;
 static void Event(WeaponSkillExpansion.Observation e){if(e.stage=="release"){releases++;probe.Check(sample+"-release-animation-"+releases,CP05Training.Instance.Hero.GetComponent<FantasyActorVisual>().Motion=="Attack","real visual action active at physical release");}if((e.stage=="release"&&e.pulse==0||e.stage=="field-pulse")&&captures<4){probe.Capture(sample+"-"+(++captures)+"-"+e.stage);}Write(new EventRow{skill=e.skill,stage=e.stage,target=e.target==null?"":e.target.name,attack=e.attack,pulse=e.pulse,origin=e.origin,direction=e.direction,before=e.before,after=e.after,time=e.time,frame=Time.frameCount});}
 static void Health(HealthObservation e){if(e.kind==HealthObservationKind.Damage){damages++;Write(new EventRow{stage="actual-health-damage",before=e.before,after=e.after,time=Time.time,frame=Time.frameCount});}}
 static void Write(EventRow row){File.AppendAllText(probe.Root+"/"+sample+".jsonl",JsonUtility.ToJson(row)+"\n");}
 static void Melee(AdventureCombat.MeleeObservation e){Write(new EventRow{stage="melee-"+e.reason,attack=e.attack,target=e.target==null?"":e.target.name,origin=e.point,direction=e.forward,before=e.before,after=e.after,frame=Time.frameCount,time=Time.time});}
 static string Global()=>JsonUtility.ToJson(UnityEngine.Random.state);
 static void Observe(ThirdPersonHero h,CombatEnemy e){releases=damages=captures=0;h.GetComponent<WeaponSkillExpansion>().Observed+=Event;h.GetComponent<AdventureCombat>().MeleeObserved+=Melee;e.Health.Observed+=Health;}
 public static IEnumerator Run(CP6Probe p){probe=p;
 for(int w=0;w<4;w++)for(int slot=1;slot<=2;slot++){
  yield return p.Reopen();p.Setup(w);yield return new WaitForSeconds(.3f);sample="skill-"+w+"-"+slot;var h=CP05Training.Instance.Hero;var c=h.GetComponent<AdventureCombat>();var e=CP05Training.Instance.Enemies[0];var extra=e.gameObject.AddComponent<BoxCollider>();extra.center=Vector3.up;extra.size=new Vector3(.65f,1.4f,.65f);Observe(h,e);c.Expanded.Select(slot);yield return null;yield return null;string rng=Global();float hp=e.Health.Current;bool started=c.UseSkill();p.Check(sample+"-start",started&&c.Expanded.Busy&&c.SkillRemaining>c.SkillDuration-.1f,"real configured cooldown, source snapshot");p.Check(sample+"-cooldown",!c.UseSkill(),"duplicate request cannot bypass shared cooldown");yield return new WaitForSeconds(c.Expanded.Definition.charge>0?.7f:.4f);yield return new WaitForEndOfFrame();var texture=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(p.Root+"/"+sample+".png",texture.EncodeToPNG());UnityEngine.Object.Destroy(texture);yield return new WaitForSeconds(2.5f);
  p.Check(sample+"-real-damage",e.Health.Current<hp&&damages>0,"actual health observation after physical melee/projectile/field contact");p.Check(sample+"-phases",releases==c.Expanded.Definition.pulses&&!c.Expanded.Busy,"all configured releases and recovery completed");p.Check(sample+"-no-duplicate-collider",damages<=c.Expanded.Definition.pulses+(w==2&&slot==1?3:0),"extra Collider did not multiply same pulse");p.Check(sample+"-global",rng==Global(),"visuals and skill queries do not consume Unity global");
  yield return p.Reopen();p.Setup(w);yield return new WaitForSeconds(.3f);sample="wall-"+w+"-"+slot;h=CP05Training.Instance.Hero;c=h.GetComponent<AdventureCombat>();e=CP05Training.Instance.Enemies[0];Observe(h,e);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="CP06 real blocking wall";wall.transform.position=h.transform.position+new Vector3(0,1.5f,w>=2?1.5f:.75f);wall.transform.localScale=new Vector3(6,4,.18f);yield return null;c.Expanded.Select(slot);yield return null;yield return null;hp=e.Health.Current;p.Check(sample+"-cast",c.UseSkill(),"real cast with obstacle");yield return new WaitForSeconds(3);p.Check(sample+"-blocked",hp==e.Health.Current&&damages==0,"solid wall not bypassed by aim, melee, piercing or field");
  yield return p.Reopen();p.Setup(w);yield return new WaitForSeconds(.3f);sample="cancel-"+w+"-"+slot;h=CP05Training.Instance.Hero;c=h.GetComponent<AdventureCombat>();e=CP05Training.Instance.Enemies[0];Observe(h,e);c.Expanded.Select(slot);yield return null;yield return null;hp=e.Health.Current;c.UseSkill();float cd=c.SkillRemaining;c.CancelPending();yield return new WaitForSeconds(1.1f);p.Check(sample+"-no-release",e.Health.Current==hp&&releases==0&&!c.Expanded.Busy,"cancel before release cannot cause Damage");p.Check(sample+"-no-refund",c.SkillRemaining>0&&c.SkillRemaining<cd,"cooldown started at begin, never refunded");
 }
 // Real held input (virtual InputSystem device, never native/manual acceptance).
 yield return p.Reopen();p.Setup(3);yield return new WaitForSeconds(.3f);sample="charged-piercing";var hero=CP05Training.Instance.Hero;var combat=hero.GetComponent<AdventureCombat>();var target=CP05Training.Instance.Enemies[0];Observe(hero,target);var prefab=Resources.Load<GameObject>("CP05Training/Enemy");var targets=new CombatEnemy[3];targets[0]=target;for(int i=1;i<3;i++){targets[i]=UnityEngine.Object.Instantiate(prefab,hero.transform.position+new Vector3(-.25f*i,0,3+i*1.5f),Quaternion.identity).GetComponent<CombatEnemy>();targets[i].enabled=false;targets[i].target=hero;}hero.cameraTransform.position=hero.transform.position+new Vector3(0,1.25f,-5);hero.cameraTransform.rotation=Quaternion.identity;File.WriteAllText(p.Root+"/pierce-fixture.json",JsonUtility.ToJson(new Fixture{positions=targets.Select(t=>t.transform.position).ToArray(),note="Before-cast diagonal row; z distances unchanged 3/4.5/6, camera ray at torso height 1.25 instead of pre-animation idle muzzle height. Downward ground-block and world-Z failures retained, no target movement after fire."},true));combat.Expanded.Select(2);var keyboard=InputSystem.AddDevice<Keyboard>();yield return null;yield return null;PlayerInput.Focus(true);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.F));yield return null;yield return null;if(!combat.Expanded.Busy)combat.UseSkill();yield return new WaitForSeconds(.65f);p.Check("charge-held",combat.Expanded.Busy&&combat.Expanded.Phase=="Charging"&&combat.Expanded.ChargeFraction>.5f,"actual Held reader on virtual keyboard; no physical input claim");InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return new WaitForSeconds(1);p.Check("pierce-three-physical-targets",targets.All(x=>x.Health.Current<x.Health.maxHealth),"one actual arrow swept three distinct real targets");InputSystem.RemoveDevice(keyboard);yield return null;yield return null;
 // Pause an already emitted projectile, then switch source weapon without erasing it.
 yield return p.Reopen();p.Setup(3);yield return new WaitForSeconds(.3f);sample="pause-switch";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];var cc=target.GetComponent<CharacterController>();cc.enabled=false;target.transform.position=hero.transform.position+Vector3.forward*20;cc.enabled=true;hero.cameraTransform.position=hero.transform.position+new Vector3(0,combat.MuzzlePosition.y,-5);hero.cameraTransform.LookAt(target.transform.position+Vector3.up*combat.MuzzlePosition.y);Observe(hero,target);combat.Expanded.Select(2);yield return null;yield return null;combat.UseSkill();yield return new WaitForSeconds(.75f);var shot=UnityEngine.Object.FindFirstObjectByType<SkillPiercingProjectile>();p.Check("pierce-emitted",shot!=null,"genuine post-release projectile exists");if(shot!=null){hero.Inventory.SetOpen(true);Vector3 pos=shot.transform.position;clock=Time.time;float cd=combat.SkillRemaining;yield return p.Wait(()=>false,.6f);p.Check("pause-flight-clock",shot!=null&&shot.transform.position==pos&&Time.time==clock&&combat.SkillRemaining==cd,"movement, lifetime, cooldown frozen");hero.Inventory.SetOpen(false);yield return null;yield return null;combat.Gear.SelectMain(combat.Gear.items.First(x=>x.type==GearType.Sword&&x.InBag));p.Check("switch-keeps-released-shot",shot!=null,"source gear clone decoupled from current weapon");yield return new WaitForSeconds(1.4f);p.Check("resumed-flight-real-hit",target.Health.Current<target.Health.maxHealth,"physical collision after resume, no injected hit");}
 // Genuine inventory pause cancels startup and subsequent sequence; no cooldown refund.
 yield return p.Reopen();p.Setup(0);yield return new WaitForSeconds(.3f);sample="pause-startup";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];Observe(hero,target);combat.Expanded.Select(1);yield return null;yield return null;combat.UseSkill();hero.Inventory.SetOpen(true);yield return p.Wait(()=>false,.4f);p.Check("pause-cancels-startup",!combat.Expanded.Busy&&releases==0,"original Ready barrier cancels unreleased phases");hero.Inventory.SetOpen(false);yield return new WaitForSeconds(.4f);p.Check("pause-no-resume-replay",releases==0&&target.Health.Current==target.Health.maxHealth,"resume does not replay canceled sequence");
 // Spear full hold: actual input reader and real release, no stat override.
 yield return p.Reopen();p.Setup(1);yield return new WaitForSeconds(.3f);sample="charged-spear";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];Observe(hero,target);combat.Expanded.Select(1);keyboard=InputSystem.AddDevice<Keyboard>();yield return null;yield return null;PlayerInput.Focus(true);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.F));yield return null;yield return null;if(!combat.Expanded.Busy)combat.UseSkill();yield return new WaitForSeconds(.55f);p.Check("spear-held-charge",combat.Expanded.Busy&&combat.Expanded.ChargeFraction>.5f,"virtual Held reader, minimum and charged real samples separate");InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return new WaitForSeconds(.6f);p.Check("spear-charge-real-hit",target.Health.Current<target.Health.maxHealth&&releases==1,"single narrow physical thrust");InputSystem.RemoveDevice(keyboard);yield return null;yield return null;
 // A released field freezes across pause, rather than replaying or accumulating pulses.
 yield return p.Reopen();p.Setup(2);yield return new WaitForSeconds(.3f);sample="field-pause";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];Observe(hero,target);combat.Expanded.Select(1);yield return null;yield return null;combat.UseSkill();yield return p.Wait(()=>UnityEngine.Object.FindFirstObjectByType<SkillImpactField>()!=null,2);var field=UnityEngine.Object.FindFirstObjectByType<SkillImpactField>();p.Check("field-real-impact-created",field!=null,"only physical projectile resolved can create field");if(field!=null){hero.Inventory.SetOpen(true);float hp=target.Health.Current;clock=Time.time;yield return p.Wait(()=>false,.7f);p.Check("field-pause-no-extra-damage",field!=null&&target.Health.Current==hp&&Time.time==clock,"elapsed time and damage pulses frozen");hero.Inventory.SetOpen(false);yield return new WaitForSeconds(2);p.Check("field-resume-real-damage",target.Health.Current<hp&&UnityEngine.Object.FindObjectsByType<SkillImpactField>().Length==0,"three real pulses finish and field expires");}
 // New attacks reuse the existing bounded melee assist, with unchanged camera pose.
 yield return p.Reopen();p.Setup(0);yield return new WaitForSeconds(.3f);sample="assisted-sword";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];cc=target.GetComponent<CharacterController>();cc.enabled=false;target.transform.position=hero.transform.position+new Vector3(.4f,0,1.5f);cc.enabled=true;hero.cameraTransform.LookAt(target.transform.position+Vector3.up);target.enabled=true;Observe(hero,target);CombatAssistOptions.Melee=true;combat.Expanded.Select(1);yield return null;yield return null;Quaternion view=hero.cameraTransform.rotation;combat.UseSkill();yield return new WaitForSeconds(1);float angle=Quaternion.Angle(Quaternion.identity,hero.transform.rotation);p.Check("melee-assist-bounded",angle>0&&angle<=30.01f&&hero.cameraTransform.rotation==view,"existing 30 degree budget, no forced camera rotation");p.Check("melee-assist-real-contact",damages>0,"target selection not substituted for hit");
 yield return p.Reopen();p.Setup(2);yield return new WaitForSeconds(.3f);sample="assisted-echo";hero=CP05Training.Instance.Hero;combat=hero.GetComponent<AdventureCombat>();target=CP05Training.Instance.Enemies[0];target.enabled=true;Observe(hero,target);CombatAssistOptions.Ranged=true;combat.Expanded.Select(2);yield return null;yield return null;view=hero.cameraTransform.rotation;combat.UseSkill();yield return new WaitForSeconds(1.5f);p.Check("ranged-assist-real-contact",damages>0&&combat.Assist.Selected!=null&&hero.cameraTransform.rotation==view,"unchanged TargetAssist, actual projectiles and freely owned camera");
 // Cleanup observed at actual training scene replacement.
 var old=CP05Training.Instance.Hero;yield return p.Reopen();p.Check("scene-cleanup",old==null&&UnityEngine.Object.FindObjectsByType<SkillImpactField>().Length==0&&UnityEngine.Object.FindObjectsByType<SkillPiercingProjectile>().Length==0,"scene-owned effects do not survive replacement");
 }
}
